/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    format = format.Replace("#.##", "0.##");

    var formatSpan = format.AsSpan();

    if (ContainsOrdinalIgnoreCase(formatSpan, TerabyteSymbol))
        return FormatValue(Terabytes, format, TerabyteSymbol, formatProvider);

    if (ContainsOrdinalIgnoreCase(formatSpan, GigabyteSymbol))
        return FormatValue(Gigabytes, format, GigabyteSymbol, formatProvider);

    if (ContainsOrdinalIgnoreCase(formatSpan, MegabyteSymbol))
        return FormatValue(Megabytes, format, MegabyteSymbol, formatProvider);

    if (ContainsOrdinalIgnoreCase(formatSpan, KilobyteSymbol))
        return FormatValue(Kilobytes, format, KilobyteSymbol, formatProvider);

    if (format.Contains(ByteSymbol, StringComparison.Ordinal))
        return FormatValue(Bytes, format, ByteSymbol, formatProvider);

    if (format.Contains(BitSymbol, StringComparison.Ordinal))
        return FormatValue(Bits, format, BitSymbol, formatProvider);

    GetLargestWholeNumber(out var value, out var symbol);
    return string.Create(formatProvider, $"{value.ToString(format, formatProvider)} {symbol}");
}

private static bool ContainsOrdinalIgnoreCase(ReadOnlySpan<char> source, string value)
    => source.Contains(value.AsSpan(), StringComparison.OrdinalIgnoreCase);

private static string FormatValue(double numericValue, string format, string unitSymbol, IFormatProvider formatProvider)
{
    // Strip the unit symbol from the format before passing to numeric formatting
    var numericFormat = format.Replace(unitSymbol, unitSymbol, StringComparison.OrdinalIgnoreCase);
    return numericValue.ToString(numericFormat, formatProvider);
}

